        PlaybackRecord placeholder=new PlaybackRecord();placeholder.source="com.netflix.ninja";placeholder.sourceLabel="Netflix";placeholder.title=MediaRecordPolicy.displayTitle("","Netflix",placeholder.source);placeholder.command="media/session";placeholder.videoId=MediaRecordPolicy.identity(placeholder.source,"",placeholder.title,"","",0);check(placeholder.valid()&&placeholder.generic(),"sessions without usable titles still produce a validated record");check(!MediaRecordPolicy.identifiable(placeholder)&&!placeholder.canResume()&&placeholder.actionLabel().equals("打开应用"),"placeholder records never claim exact resume or live continuation");check(GenericMediaHistory.actionFor(placeholder,placeholder.key()).equals("打开应用"),"a matching placeholder session still opens its app instead of claiming resume");placeholder.contentId=MediaRecordPolicy.digest("ep-1");check(MediaRecordPolicy.identifiable(placeholder),"a known media ID identifies the held item");check(GenericMediaHistory.actionFor(placeholder,placeholder.key()).equals("恢复当前播放")&&GenericMediaHistory.actionFor(placeholder,null).equals("打开应用"),"only the same identifiable live session gets the resume label");PlaybackRecord titled=new PlaybackRecord();titled.source="com.example.player";titled.sourceLabel="Player";titled.title="Series";titled.videoId=MediaRecordPolicy.identity(titled.source,"",titled.title,"","",0);check(MediaRecordPolicy.identifiable(titled),"real titles identify the held item without a media ID");
        String stable=MediaRecordPolicy.identity("com.example.player","ep-3","Series","第 3 集","",0);check(stable.equals(MediaRecordPolicy.identity("com.example.player","ep-3","Series","第 3 集","",300000)),"late duration does not create a duplicate record");check(!stable.equals(MediaRecordPolicy.identity("com.example.player","ep-3","Series","第 4 集","",0)),"reused series IDs still distinguish supplied episode labels");check(!stable.equals(MediaRecordPolicy.identity("com.other.player","ep-3","Series","第 3 集","",0)),"content identities remain isolated between apps");
        PlaybackRecord a=new PlaybackRecord(),b=new PlaybackRecord();a.source=b.source="com.example.player";a.title=b.title="Series";a.episode=b.episode="第 3 集";check(MediaRecordPolicy.sameItem(a,b),"sparse matching labels can retain their canonical identity");a.contentId=MediaRecordPolicy.digest("ep-3");check(MediaRecordPolicy.sameItem(a,b),"late media ID enriches the same sparse record");b.contentId=MediaRecordPolicy.digest("ep-4");check(!MediaRecordPolicy.sameItem(a,b),"different known media IDs never merge");b.contentId=a.contentId;b.episode="第 4 集";check(!MediaRecordPolicy.sameItem(a,b),"different episodes never merge even with a reused media ID");b.episode=a.episode;b.source="com.other.player";check(!MediaRecordPolicy.sameItem(a,b),"app boundaries prevent metadata merge");
        check(MediaRecordPolicy.position(10000,60000,true,1f,1000,6000)==15000,"playing position advances with elapsed realtime");check(MediaRecordPolicy.position(10000,60000,false,1f,1000,6000)==10000,"paused position does not advance");check(MediaRecordPolicy.position(59000,60000,true,1f,1000,6000)==60000,"estimated progress remains within duration");check(MediaRecordPolicy.position(-1,60000,true,1f,1000,6000)==0,"unknown positions do not fabricate progress");check(MediaRecordPolicy.position(10000,60000,true,Float.NaN,1000,6000)==10000,"invalid playback speed cannot corrupt positions");check(MediaRecordPolicy.position(10000,60000,true,1f,6000,1000)==10000,"clock reversal cannot advance progress");check(MediaRecordPolicy.position(Long.MAX_VALUE,0,true,16f,1,Long.MAX_VALUE)==259200000L,"overflow positions remain bounded");
