        check(MediaArtwork.local("localart:"+MediaRecordPolicy.digest("art")),"bounded local artwork reference accepted");check(!MediaArtwork.local("localart:../../private")&&!MediaArtwork.local("file:///data/private"),"artwork references cannot traverse private files");check(!MediaArtwork.safeRemote("https://pic0.iqiyipic.com/image/a.jpg").isEmpty(),"public Qiyi artwork accepted");check(MediaArtwork.safeRemote("https://pic0.iqiyipic.com.evil.example/image/a.jpg").isEmpty(),"artwork host lookalikes rejected");check(MediaArtwork.safeRemote("https://assets.nflximg.net/image/a.jpg?token=secret").isEmpty(),"generic artwork does not download credential-bearing URLs");check(MediaArtwork.safeRemote("https://192.168.1.1/image/a.jpg").isEmpty(),"metadata cannot trigger local network downloads");
        a.source=b.source="com.example.player";a.title=b.title="Series";a.contentId=b.contentId=MediaRecordPolicy.digest("episode-3");a.episode="";b.episode="第 3 集";a.videoId=MediaRecordPolicy.digest("late");b.videoId=MediaRecordPolicy.digest("initial");check(MediaRecordPolicy.sameItem(a,b),"sparse update with matching known content ID retains supplied episode label");MediaRecordPolicy.retainIdentity(a,b);check(a.videoId.equals(b.videoId)&&a.episode.equals("第 3 集"),"late identity fields cannot recreate a removed playing item");a.positionKnown=false;a.position=0;b.positionKnown=true;b.position=123000;b.duration=600000;a.inheritMetadata(b);check(a.positionKnown&&a.position==123000&&a.duration==600000,"stopped metadata preserves the last known progress and duration");a.episode="第 4 集";check(!MediaRecordPolicy.sameItem(a,b),"nonempty different episode labels still separate reused IDs");
