    private static void viewportChecks(){
        int[] tops={4,185,366,547,728},bottoms={177,358,539,720,901};
        check(RowViewport.reveal(tops,bottoms,1,540,190,400)==185,"upward focus recovers three complete rows instead of retaining only two");
        check(RowViewport.reveal(tops,bottoms,0,540,190,400)==0,"the first row returns to the desktop heading");
        check(RowViewport.reveal(new int[0],new int[0],0,0,0,0)==0,"empty and unmeasured viewports are safe");
        java.util.Random random=new java.util.Random(28);
        for(int example=0;example<100;example++){
            int[] a=new int[9],b=new int[9];int cursor=4;for(int i=0;i<a.length;i++){a[i]=cursor;b[i]=cursor+80+random.nextInt(130);cursor=b[i]+8+random.nextInt(30);}
            int height=360+random.nextInt(180),maximum=cursor-height,focused=1+random.nextInt(8),current=random.nextInt(maximum+1);
            int chosen=RowViewport.reveal(a,b,focused,height,current,maximum);int visible=0,best=0;
            for(int i=0;i<a.length;i++)if(a[i]>=chosen&&b[i]<=chosen+height)visible++;
            for(int y=Math.max(0,b[focused]-height);y<=Math.min(maximum,a[focused]);y++){int count=0;for(int i=0;i<a.length;i++)if(a[i]>=y&&b[i]<=y+height)count++;best=Math.max(best,count);}
            check(chosen>=0&&chosen<=maximum&&a[focused]>=chosen&&b[focused]<=chosen+height,"viewport retains focused row within actual content bounds");
            check(visible==best,"mixed row heights maximize complete visible rows in both directions");
        }
        PlaybackRecord configured=new PlaybackRecord();configured.source="org.example.player";configured.command="rule/broadcast";configured.videoId=MediaRecordPolicy.digest("stable");configured.title="Example";configured.ruleId="example.player";configured.ruleData.put("id","abc_123");
        check(configured.valid(),"configured history keeps a bounded app identity and content ID");String identity=configured.key();configured.ruleId="example.player-v2";check(identity.equals(configured.key()),"rule versions and rule names never enter history identity");configured.ruleData.put("id","https://private.example/play");check(!configured.valid(),"playback URLs cannot enter configured history storage");
    }
